let main = function() {
    // MaterialComponent.base_color uses linear RGB; match the flange sRGB #b0b0b0.
    const gray = Math.pow((176 / 255 + 0.055) / 1.055, 2.4);
    const materialJson = JSON.stringify(JSON.parse(part3dJson, (key, value) =>
        key === "base_color" && Array.isArray(value) ? [gray, gray, gray] : value));
    const doc = PartCode3dDocument.create_doc_from_part3d(materialJson, true);
    if (!doc) throw new Error("无法重建高速轴特征树");
    return doc;
};
